import 'package:flutter/material.dart';
class OnboardingScreen extends StatefulWidget { const OnboardingScreen({super.key}); @override State<OnboardingScreen> createState() => _OnboardingScreenState(); }
class _OnboardingScreenState extends State<OnboardingScreen> { final PageController controller = PageController(); int index = 0; final List<(IconData, String, String)> pages = <(IconData, String, String)>[(Icons.explore, 'اكتشف تخصصك المناسب', 'حلل اهتماماتك وقدراتك بثقة.'), (Icons.quiz, 'اختبر ميولك ومهاراتك', 'أجب على أسئلة مدروسة واحصل على تحليل ذكي.'), (Icons.auto_awesome, 'احصل على توصيات مخصصة', 'شاهد نسبة توافقك مع التخصصات.'), (Icons.forum, 'تواصل مع مستشار', 'احجز موعداً أو ابدأ استشارة فورية.')]; @override void dispose() { controller.dispose(); super.dispose(); } @override Widget build(BuildContext context) { return Scaffold(body: SafeArea(child: Column(children: <Widget>[Align(alignment: Alignment.centerLeft, child: TextButton(onPressed: () => Navigator.pushReplacementNamed(context, '/login'), child: const Text('تخطي'))), Expanded(child: PageView.builder(controller: controller, itemCount: pages.length, onPageChanged: (int value) => setState(() => index = value), itemBuilder: (BuildContext context, int pageIndex) { final item = pages[pageIndex]; return Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: <Widget>[Icon(item.$1, size:88, color: Theme.of(context).colorScheme.primary), const SizedBox(height:30), Text(item.$2, style: Theme.of(context).textTheme.headlineSmall, textAlign: TextAlign.center), const SizedBox(height:12), Text(item.$3, textAlign: TextAlign.center)])); })), Padding(padding: const EdgeInsets.all(24), child: FilledButton(onPressed: () { if (index == pages.length - 1) { Navigator.pushReplacementNamed(context, '/login'); } else { controller.nextPage(duration: const Duration(milliseconds: 250), curve: Curves.easeOut); } }, child: Text(index == pages.length - 1 ? 'ابدأ الآن' : 'التالي')))]))); } }
